# 2.1 Description > • Test Case Design Methodology

Here's an example implementation in C for I2C EEPROM testing:

/ I2C EEPROM Read/Write Test Case Purpose: Validates I2C communication and EEPROM functionality Success Criteria: Write/read verification with <5% bit error rate / int test_i2c_eeprom(uint8_t device_address) { int fd; uint8_t test_data[] = "BeagleTester"; uint8_t read_data[sizeof(test_data)]; uint8_t reg_addr = 0x00; int error_count = 0; float error_rate = 0.0; // Open I2C bus if ((fd = open("/dev/i2c-2", O_RDWR)) < 0) { log_error("Failed to open I2C bus"); return** -1; }

// Set slave address if (ioctl(fd, I2C_SLAVE, device_address) < 0) { log_error("Failed to acquire bus access"); close(fd); return -1; } // write to EEPROM if (i2c_smbus_write_i2c_block_data(fd, reg_addr, sizeof(test_data), test_,→data) < 0) { log_error("Failed to write to EEPROM"); close(fd); return -1; } usleep(100000); // 100ms delay // read back data if (i2c_smbus_read_i2c_block_data(fd, reg_addr, sizeof(test_data), read_,→data) < 0) { log_error("Failed to read from EEPROM"); close(fd); return -1; } // error rate calc for (int i = 0; i < sizeof(test_data); i++) { if (test_data[i]!= read_data[i]) error_count++; } error_rate = (float)error_count / sizeof(test_data) 100.0; // logging log_info("I2C EEPROM Test: %s", (error_rate < 5.0)? "PASS": "FAIL"); log_info("Bit Error Rate: %.2f%%", error_rate); // Cleanup memset(test_data, 0xFF, sizeof(test_data)); i2c_smbus_write_i2c_block_data(fd, reg_addr, sizeof(test_data), test_,→*data); close(fd); return (error_rate < 5.0)? 0: -1; }

